-- IskolarLink seed data: applicants, applications, history, grant schedules (FICTIONAL DATA ONLY)
-- Run AFTER schema.sql and seed.sql (it needs the users, programs and tiers from seed.sql).
-- RE-RUNNABLE: it first deletes every applicant, application, history row and grant schedule,
-- so anything you added by hand in those tables is lost. Users, programs and tiers are untouched.
-- Emails and phone numbers are made up (example.com and 0917-000-xxxx are not real).
-- Generated by a script so each application's history matches its phase and satisfies the
-- schema constraints (an ineligible result has a reason, a tier only on eligible results).

USE iskolarlink;

DELETE FROM grant_schedules;
DELETE FROM status_history;
DELETE FROM applications;
DELETE FROM applicants;
ALTER TABLE grant_schedules AUTO_INCREMENT = 1;
ALTER TABLE status_history AUTO_INCREMENT = 1;
ALTER TABLE applications AUTO_INCREMENT = 1;
ALTER TABLE applicants AUTO_INCREMENT = 1;




